int aac_pci_probe ( parent , match , aux ) device * parent ; void * match ; void * aux ; { struct pci_attach_args * pa = aux ; struct aac_ident * m ; for ( m = aac_identifiers ; m -> vendor != 0 ; m ++ ) { if ( m -> vendor == PCI_VENDOR ( pa -> pa_id ) && m -> device == PCI_PRODUCT ( pa -> pa_id ) ) { subsysid = pci_conf_read ( pa -> pa_pc , pa -> pa_tag , PCI_SUBSYS_ID_REG ) ; if ( m -> subvendor == PCI_VENDOR ( subsysid ) && m -> subdevice == PCI_PRODUCT ( subsysid ) ) { return ( 1 ) ; } } } return ( 0 ) ; } 